from collections import deque

def dinic_max_flow(graph, source, sink, n):
    INF = 10**9
    level = [-1] * n
    ptr = [0] * n

    def bfs():
        for i in range(n):
            level[i] = -1
        queue = deque()
        level[source] = 0
        queue.append(source)
        while queue:
            u = queue.popleft()
            for idx, (v, cap) in enumerate(graph[u]):
                if cap > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[sink] != -1

    def dfs(u, flow):
        if u == sink or flow == 0:
            return flow
        for i in range(ptr[u], len(graph[u])):
            ptr[u] = i
            v, cap = graph[u][i]
            if level[v] == level[u] + 1 and cap > 0:
                pushed = dfs(v, min(flow, cap))
                if pushed > 0:
                    graph[u][i] = (v, cap - pushed)
                    graph[v][rev_index[u][i]] = (u, graph[v][rev_index[u][i]][1] + pushed)
                    return pushed
        return 0

    rev_index = [[0] * len(adj) for adj in graph]
    for u in range(n):
        for idx, (v, cap) in enumerate(graph[u]):
            rev_index[u][idx] = len(graph[v])
            graph[v].append((u, 0))

    total_flow = 0
    while bfs():
        for i in range(n):
            ptr[i] = 0
        while True:
            pushed = dfs(source, INF)
            if pushed == 0:
                break
            total_flow += pushed
    return total_flow

