from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        print(-1)
        return

    n = int(data[0])
    if n < 5:
        print(-1)
        return

    graph = [[] for _ in range(n+1)]
    index = 1
    for _ in range(n-1):
        a = int(data[index]); b = int(data[index+1]); index += 2
        graph[a].append(b)
        graph[b].append(a)

    parent = [-1] * (n+1)
    children = [[] for _ in range(n+1)]
    stack = [1]
    parent[1] = 0
    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in graph[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            children[u].append(v)
            stack.append(v)

    NEG_INF = -10**18
    dp = [[[NEG_INF] * 2 for _ in range(5)] for __ in range(n+1)]

    for v in order[::-1]:
        best = [[NEG_INF] * 2 for _ in range(5)]
        best[0][0] = 1

        for u in children[v]:
            new_best = [row[:] for row in best]

            for a in range(5):
                for h_child in range(2):
                    if best[a][h_child] == NEG_INF:
                        continue
                    current_size = best[a][h_child]

                    for h_u in range(2):
                        if dp[u][0][h_u] != NEG_INF:
                            new_a = a + 1
                            if new_a > 4:
                                continue
                            new_h_child = h_child | h_u
                            new_size = current_size + dp[u][0][h_u]
                            if new_size > new_best[new_a][new_h_child]:
                                new_best[new_a][new_h_child] = new_size

                    if dp[u][3][1] != NEG_INF:
                        new_a = a + 1
                        if new_a > 4:
                            continue
                        new_h_child = h_child | 1
                        new_size = current_size + dp[u][3][1]
                        if new_size > new_best[new_a][new_h_child]:
                            new_best[new_a][new_h_child] = new_size

            best = new_best

        for a in range(5):
            for h_child in range(2):
                if best[a][h_child] == NEG_INF:
                    continue
                h_final = h_child | (1 if a == 4 else 0)
                if best[a][h_child] > dp[v][a][h_final]:
                    dp[v][a][h_final] = best[a][h_child]

    ans = -1
    for v in range(1, n+1):
        for a in [1, 4]:
            if dp[v][a][1] > ans:
                ans = dp[v][a][1]

    print(ans)

