    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        # Read H and W
        hw_line = data[index].split()
        index += 1
        H = int(hw_line[0])
        W = int(hw_line[1])

        grid = []
        for _ in range(H):
            grid.append(data[index])
            index += 1

        # Check each row has even number of 'A'
        valid = True
        for i in range(H):
            count_a = grid[i].count('A')
            if count_a % 2 != 0:
                valid = False
                break

        if valid:
            # Check each column has even number of 'A'
            for j in range(W):
                count_a = 0
                for i in range(H):
                    if grid[i][j] == 'A':
                        count_a += 1
                if count_a % 2 != 0:
                    valid = False
                    break

        if valid:
            results.append("2")
        else:
            results.append("0")

    print("\n".join(results))

